def select_next_node(graph, unvisited_nodes):
    # Read precomputed global features
    degree_variance = graph.graph['precomputed']['degree_variance']
    apl_lcc = graph.graph['precomputed']['apl_lcc']

    nodes = unvisited_nodes
    # Extract node features
    betweenness = {n: graph.nodes[n]['betweenness'] for n in nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in nodes}
    degree = {n: graph.nodes[n]['degree'] for n in nodes}
    eigenvector = {n: graph.nodes[n]['eigenvector'] for n in nodes}

    # Normalize features to [0,1]
    def normalize(d):
        vals = list(d.values())
        min_v, max_v = min(vals), max(vals)
        if max_v - min_v < 1e-12:
            return {k:0 for k in d}
        return {k: (v - min_v)/(max_v - min_v) for k,v in d.items()}

    bet_n = normalize(betweenness)
    clust_n = normalize(clustering)
    deg_n = normalize(degree)
    eig_n = normalize(eigenvector)

    # Adaptive weights based on global degree variance and average path length
    w_deg = 0.5 * (degree_variance / (degree_variance + 1)) + 0.1
    w_clust = 0.4 * (apl_lcc / (apl_lcc + 1)) + 0.1
    # Inverse weighting for betweenness and eigenvector to diversify selection
    w_bet = 0.3 * (1 - min(1, bet_n[max(bet_n, key=bet_n.get)])) + 0.1
    w_eig = 0.3 * (1 - min(1, eig_n[max(eig_n, key=eig_n.get)])) + 0.1

    scores = {}
    for n in nodes:
        score = (
            w_deg * deg_n[n] + 
            w_clust * (1 - clust_n[n]) +
            w_bet * (1 - bet_n[n]) +
            w_eig * (1 - eig_n[n])
        )
        scores[n] = score

    next_node = max(scores, key=scores.get)
    return next_node

def select_next_node(graph, unvisited_nodes):
    # Precomputed global feature
    bridge_high_bc = graph.graph['precomputed']['bridge_ratio_high_bc']

    nodes = unvisited_nodes
    # Extract node features
    betweenness = {n: graph.nodes[n]['betweenness'] for n in nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in nodes}
    core_num = {n: graph.nodes[n]['core_number'] for n in nodes}
    degree = {n: graph.nodes[n]['degree'] for n in nodes}

    # Normalize features to [0,1] to combine fairly
    def normalize(d):
        vals = list(d.values())
        min_v, max_v = min(vals), max(vals)
        if max_v - min_v < 1e-12:
            return {k:0 for k in d}
        return {k: (v - min_v)/(max_v - min_v) for k,v in d.items()}

    betweenness_n = normalize(betweenness)
    clustering_n = normalize(clustering)
    core_num_n = normalize(core_num)
    degree_n = normalize(degree)

    # Weights dynamically adjusted by bridge_ratio_high_bc (range assumed near [0,1])
    # Higher bridge_ratio_high_bc -> emphasize betweenness and core_number (targets bridges & cores)
    # Lower bridge_ratio_high_bc -> emphasize degree and inverse clustering (targets hubs, weakly clustered)
    w_bet = 0.5 * bridge_high_bc + 0.1
    w_core = 0.3 * bridge_high_bc + 0.1
    w_deg = 0.4 * (1 - bridge_high_bc) + 0.1
    w_clust = 0.3 * (1 - bridge_high_bc) + 0.1

    scores = {}
    for n in nodes:
        score = (
            w_bet * betweenness_n[n] + 
            w_core * core_num_n[n] + 
            w_deg * degree_n[n] + 
            w_clust * (1 - clustering_n[n])
        )
        scores[n] = score

    # Select node with highest combined score
    next_node = max(scores, key=scores.get)
    return next_node
